cd /home/vercel-sandbox/native; cat > /tmp/c1.py <<'E'
import re,glob
for f in glob.glob('components/**/*.py',recursive=True):
    s=open(f).read(); o=s
    s=re.sub(r'(\*{1,2}\w+): Any\b',r'\1: PropValue',s)
    if s==o: continue
    if f.endswith('core/core.py'):
        s=s.replace('\nPACKAGE_CN','\nPropValue = Any\nPACKAGE_CN',1)
    elif f.startswith('components/core/'):
        s=s.replace('from reflex','from .core import PropValue\nfrom reflex',1) if False else s
        print('manual',f)
    elif 'chart' in f: print('manual',f)
    else:
        if re.search(r'^from \.\.core\.core import ',s,re.M):
            s=re.sub(r'^from \.\.core\.core import (.*)$',lambda m:'from ..core.core import '+', '.join(sorted(set(m.group(1).split(', '))|{'PropValue'},key=lambda x:(x.lower()))) ,s,count=1,flags=re.M)
        else:
            print('manual',f); 
    open(f,'w').write(s)
E
