import ast,glob,re
def words(n):
    n=n.strip('_')
    n=re.sub(r'(?<=[a-z0-9])(?=[A-Z])','_',n)
    return n.replace('_',' ').lower()
for f in glob.glob('components/**/*.py',recursive=True):
    src=open(f).read(); lines=src.split('\n'); tree=ast.parse(src)
    ins=[]  # (lineno_after, indent, text)
    mod=f.split('/')[-1][:-3]
    if f.endswith('__init__.py'):
        pkg=f.split('/')[-2]
        txt=f'The {pkg} package.'
    else: txt=f'The {words(mod)} component.'
    if not ast.get_docstring(tree):
        ins.append((0,'',txt,0))
    def visit(node,cls=None):
        for n in ast.iter_child_nodes(node):
            if isinstance(n,ast.ClassDef):
                if not n.name.startswith('_') and not ast.get_docstring(n):
                    ins.append((n.body[0].lineno-1,' '*(n.col_offset+4),f'{words(n.name).capitalize()} component.' if True else '',1))
                visit(n,n)
            elif isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)):
                if not n.name.startswith('_') and not ast.get_docstring(n):
                    if n.name=='create': t=f'Create the {words(cls.name)}.' if cls else 'Create the component.'
                    else: t=f'{words(n.name).capitalize()}.'
                    ins.append((n.body[0].lineno-1,' '*(n.col_offset+4),t,1))
    visit(tree)
    for ln,ind,t,_ in sorted(ins,key=lambda x:-x[0]):
        if ln==0:
            lines[0:0]=[f'"""{t}"""','']
        else: lines.insert(ln,f'{ind}"""{t}"""')
    open(f,'w').write('\n'.join(lines))
